public class StringConcatenationDemo {
    public static void main(String[] args) {
        int val1 = 15;
        int val2 = 25;

        // 1. Left-to-right evaluation order
        System.out.println("Result 1: " + val1 + val2);       // "Result 1: 1525"
        System.out.println("Result 2: " + (val1 + val2));     // "Result 2: 40"
        System.out.println(val1 + val2 + " is the sum");     // "40 is the sum"

        // 2. Concatenation with different primitive types
        boolean active = true;
        double price = 99.95;
        String summary = "Active: " + active + " | Price: $" + price;
        System.out.println(summary);

        // 3. Null handling: + vs .concat()
        String prefix = "Status: ";
        String nullValue = null;
        System.out.println(prefix + nullValue); // "Status: null"

        // 4. Character addition before String
        // 'A' is 65, 'B' is 66 -> 65 + 66 = 131
        System.out.println('A' + 'B' + " = letters"); // "131 = letters"
        System.out.println("" + 'A' + 'B' + " = letters"); // "AB = letters"
    }
}

