practiceProblems.solutionCode:
public class NullSafeNotification {
    public static void main(String[] args) {
        String customer = null;
        String orderId = "ORD-1002";
        String displayName = (customer != null) ? customer : "Guest";
        String message = "Notification: Order " + orderId + " assigned to " + displayName;
        System.out.println(message);
    }
}

